def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in my if x == 'D')
    last_me = my[-1]
    last_opp = opp[-1]

    opp_c_run = 0
    for x in reversed(opp):
        if x == 'C':
            opp_c_run += 1
        else:
            break

    opp_d_run = 0
    for x in reversed(opp):
        if x == 'D':
            opp_d_run += 1
        else:
            break

    r = n if n < 10 else 10
    recent_d = 0
    for i in range(n - r, n):
        if opp[i] == 'D':
            recent_d += 1

    soft = 0
    punish = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'D':
                punish += 1
            else:
                soft += 1

    if opp_d_run >= 4 or recent_d >= 7:
        return 'D'
    if n >= 8 and opp_d * 2 >= n and opp_c_run < 3:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C' and n >= 2 and my[-2] == 'D':
            if opp_d_run <= 2 and recent_d <= 4 and opp_c * 4 >= opp_d:
                return 'C'

        if opp_d_run >= 3:
            return 'D'
        if opp_d_run >= 2 and opp_c <= 2:
            return 'D'
        if last_me == 'C':
            return 'D'

        if opp_d_run == 1:
            return 'C'

        if opp_d_run == 2:
            if recent_d <= 4 and opp_c * 4 >= opp_d and opp_c_run > 0:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        return 'D'

    if soft > 0 and recent_d <= 2 and opp_c * 3 >= opp_d:
        total = soft + punish
        tolerance = float(soft) / float(total) if total > 0 else 1.0

        if last_me == 'D':
            if punish == 0 and tolerance >= 0.75:
                return 'D'
            if rng.random() < (0.35 + 0.45 * tolerance):
                return 'D'
            return 'C'

        if punish == 0 and tolerance >= 0.75:
            p = 0.75 + min(0.2, 0.05 * soft)
            if rng.random() < p:
                return 'D'
            return 'C'

        if tolerance >= 0.55:
            p = 0.25 + 0.35 * tolerance
            if n >= 60:
                p = min(0.65, p + 0.1)
            if rng.random() < p:
                return 'D'
            return 'C'

    if my_d == 0 and opp_d == 0 and opp_c_run >= n:
        if n >= 25:
            return 'D'
        if n >= 15 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if last_me == 'D':
        return 'C'

    if opp_c * 4 >= n and recent_d <= 1:
        if n >= 90 and (punish == 0 or opp_c * 5 >= n):
            if rng.random() < 0.22:
                return 'D'
        elif punish == 0 and opp_c * 5 >= n and n >= 60:
            if rng.random() < 0.08:
                return 'D'

    return 'C'
